def store(data, actor, inbox_id=None, card_id=None):
    """Кладёт данные в карточку.
    Новая карточка заводится ТОЛЬКО когда есть VIN.
    Заполненные поля никогда не затираются — дописываются лишь пустые.
    Возвращает (card_id, номер, признак новой) или (None, None, None),
    если заводить нечего.
    """
    existing = None
    if card_id:
        existing = db.get_card("cars", int(card_id))
    if not existing and data.get("vin"):
        existing = find_by_vin(data["vin"])

    if existing:
        card_id = existing["id"]
        for field, value in data.items():
            if existing.get(field) in (None, "", 0):
                db.update_card_field("cars", card_id, field, value, actor)
        number = existing.get("auto_number")
        if not number:
            with db.connect() as c:
                number = S.next_auto_number(c)
            db.update_card_field("cars", card_id, "auto_number", number, actor)
        novaya = False
    else:
        if not data.get("vin"):
            return None, None, None          # без VIN новую не заводим
        legacy = {k: v for k, v in {
            "brand": data.get("brand"), "model": data.get("model"),
            "year": data.get("year"), "vin": data.get("vin"),
            "fuel": data.get("fuel"), "color": data.get("color"),
        }.items() if v}
        card_id = db.create_card("cars", legacy, actor)
        with db.connect() as c:
            number = S.next_auto_number(c)
        db.update_card_field("cars", card_id, "auto_number", number, actor)
        for field, value in data.items():
            db.update_card_field("cars", card_id, field, value, actor)
        db.set_card_review("cars", card_id, db.ST_APPROVED_OWNER, actor, publish=False)
        novaya = True

    if inbox_id:
        # Присланное сообщение к карточке не прикрепляем: скриншоты и документы
        # в галерею попадать не должны. Фото добавляются только кнопкой.
        try:
            db.link_inbox_card(inbox_id, "cars", card_id, actor)
            db.set_inbox_status(inbox_id, db.ST_APPROVED_OWNER, actor)
        except Exception:
            pass

    return card_id, number, novaya

async def save(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    staff = db.get_staff(q.from_user.id)
    draft = context.user_data.get("ai_draft")
    if not draft or not staff:
        return                      # пусть отработает обычный обработчик

    parsed = draft.get("parsed") or {}
    if parsed.get("type") == "client":
        return                      # клиентов не трогаем

    data = clean(parsed)
    if not data:
        await q.message.reply_text("Из сообщения нечего взять в карточку.")
        raise ApplicationHandlerStop

    existing = find_by_vin(data.get("vin"))
    actor = staff["user_id"]

    if existing:
        card_id = existing["id"]
        for field, value in data.items():
            if not existing.get(field):
                db.update_card_field("cars", card_id, field, value, actor)
        note = "Дополнил карточку %s." % (existing.get("auto_number") or "#%d" % card_id)
    else:
        legacy = {"brand": data.get("brand"), "model": data.get("model"),
                  "year": data.get("year"), "vin": data.get("vin"),
                  "fuel": data.get("fuel"), "color": data.get("color")}
        legacy = {k: v for k, v in legacy.items() if v}
        card_id = db.create_card("cars", legacy, actor)
        with db.connect() as c:
            number = S.next_auto_number(c)
        db.update_card_field("cars", card_id, "auto_number", number, actor)
        for field, value in data.items():
            db.update_card_field("cars", card_id, field, value, actor)
        db.set_card_review("cars", card_id, db.ST_APPROVED_OWNER, actor, publish=False)
        note = "Открыл новую карточку %s." % number

    # переносим фото и видео из входящего сообщения
    try:
        import team_bot
        foto, video = team_bot.collect_media(draft["inbox_id"])
        if foto:
            import json
            card = db.get_card("cars", card_id)
            have = []
            try:
                have = json.loads(card.get("photos") or "[]")
            except Exception:
                have = []
            norm = [p if isinstance(p, dict) else {"file_id": p, "tag": ""} for p in have]
            for f in foto:
                if not any(p.get("file_id") == f for p in norm):
                    norm.append({"file_id": f, "tag": ""})
            db.update_card_field("cars", card_id, "photos",
                                 json.dumps(norm, ensure_ascii=False), actor)
            try:
                import photo_hide
                photo_hide.archive(card_id, foto, actor)
            except Exception as e:
                log.warning("Архив служебных фото: %s", e)
        if video:
            db.update_card_field("cars", card_id, "video_h", video[0], actor)
    except Exception as e:
        log.warning("Медиа не перенеслись: %s", e)

    try:
        db.link_inbox_card(draft["inbox_id"], "cars", card_id, actor)
        db.set_inbox_status(draft["inbox_id"], db.ST_APPROVED_OWNER, actor)
    except Exception:
        pass

    context.user_data.pop("ai_draft", None)
    card = db.get_card("cars", card_id)
    await q.message.edit_reply_markup(reply_markup=None)
    await q.message.reply_text(
        note,
        reply_markup=InlineKeyboardMarkup([[
            InlineKeyboardButton("Открыть карточку", callback_data="car_open:%d" % card_id)],
            [InlineKeyboardButton("Дозаполнить", callback_data="car_edit:%d" % card_id)]]))
    raise ApplicationHandlerStop

def ensure_columns():
    """Добавляет колонки, которых нет ни в старой схеме, ни в cars_schema."""
    extra = [("price_history", "TEXT"), ("cover_photo", "TEXT"),
             ("eta_manual", "TEXT")]
    with db.connect() as c:
        have = {r["name"] for r in c.execute("PRAGMA table_info(cars)").fetchall()}
        for name, decl in extra:
            if name not in have:
                try:
                    c.execute("ALTER TABLE cars ADD COLUMN %s %s" % (name, decl))
                    log.info("Добавлена колонка cars.%s", name)
                except Exception as e:
                    log.warning("Не добавил cars.%s: %s", name, e)

def apply_value(card_id, field, raw, actor_id):
    """Возвращает (ок, сообщение). Ничего не додумывает."""
    value = (raw or "").strip()
    if not value:
        return False, "Пустое значение не записываю."

    if field == "eta_days":
        digits = "".join(ch for ch in value if ch.isdigit())
        if not digits:
            return False, "Пришлите число дней, например 45."
        n = int(digits)
        if n > 400:
            return False, "Слишком большой срок. Пришлите число дней."
        eta = _date.today() + _td(days=n)
        set_field(card_id, "eta_manual", eta.isoformat(), actor_id)
        set_field(card_id, "days_to_kyiv", n, actor_id)
        return True, "До прибытия %d дней · %s" % (n, eta.strftime("%d.%m.%Y"))

    if field in NUMERIC:
        digits = value.lower().replace(" ", "").replace("\u00a0", "")
        for lishnee in ("цена", "стоимость", "$", "usd", "долларов", "долл"):
            digits = digits.replace(lishnee, "")
        for word, mult in (("тысяч", 1000), ("тыс", 1000), ("к", 1000)):
            if word in digits.lower():
                digits = digits.lower().split(word)[0]
                try:
                    num = int(float(digits.replace(",", ".")) * mult)
                except ValueError:
                    return False, "Не разобрал число. Пришлите цифрами."
                break
        else:
            digits = "".join(ch for ch in digits if ch.isdigit())
            if not digits:
                return False, "Не разобрал число. Пришлите цифрами."
            num = int(digits)
        if field == "engine_cc" and num < 100:
            return False, ("Похоже, это литры. Объём нужен в кубических сантиметрах — "
                           "например, 1598.")
        set_field(card_id, field, num, actor_id)
        return True, "Записано: %s" % S.num(num)

    if field == "vin":
        vin = value.upper().replace(" ", "")
        ok, msg = S.check_vin(vin)
        if not ok:
            return False, "VIN не принят: %s" % msg
        set_field(card_id, field, vin, actor_id)
        return True, "Записано: %s" % vin

    set_field(card_id, field, value, actor_id)
    return True, "Записано."

def db_clean_split():
    """Разово вычищает фразу 50/50 из описаний машин, стоящих в Грузии."""
    db = os.path.join(BASE, "crm.db")
    if not os.path.exists(db):
        return
    try:
        con = sqlite3.connect(db)
        cur = con.cursor()
        cols = [r[1] for r in cur.execute("PRAGMA table_info(cars)").fetchall()]
        if "condition_text" not in cols:
            con.close()
            return

        keys = ["rowid", "condition_text"]
        for extra in ("status", "stage"):
            if extra in cols:
                keys.append(extra)
        rows = cur.execute("SELECT %s FROM cars" % ", ".join(keys)).fetchall()

        changed = []
        for row in rows:
            data = dict(zip(keys, row))
            text = data.get("condition_text") or ""
            if "50" not in text:
                continue
            status = str(data.get("status") or "")
            stage = data.get("stage")
            in_georgia = ("Грузи" in status) or (
                isinstance(stage, int) and stage >= 3
            )
            if not in_georgia:
                continue
            new = SPLIT_RE.sub("", text)
            new = re.sub(r"\n{3,}", "\n\n", new).strip()
            if new != text:
                changed.append((new, data["rowid"]))

        if changed:
            shutil.copy2(db, db + ".bak_split")
            cur.executemany(
                "UPDATE cars SET condition_text = ? WHERE rowid = ?", changed
            )
            con.commit()
            log.info("описание почищено от 50/50 у карточек: %d", len(changed))
        con.close()
    except Exception as e:
        log.warning("чистка базы не удалась: %r", e)
